/**
 * One chat message.
 *
 * `id` is generated by the SENDING DEVICE, never by a server. That single
 * choice is what makes every retry in this system safe: a retry carries the
 * same id, so the receiver can recognise it as a repeat instead of a new
 * message. (Invariant: message identity is decided by the sender.)
 *
 * `ciphertext` is deliberately named that, not `text`: in the real system the
 * servers you see below can never read this field.
 */
record Msg(String id, String fromUser, String toUser, String convId, long seq, String ciphertext) {
    @Override public String toString() { return id + "(" + convId + "#" + seq + ")"; }
}

